import{_ as t,o as a,c as o,a5 as n}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"3.4.6 Remove Agency","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-6-remove-agency/spec.md","filePath":"feature/agency-workspace/3-4-6-remove-agency/spec.md"}'),s={name:"feature/agency-workspace/3-4-6-remove-agency/spec.md"};function i(r,e,l,c,h,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_3-4-6-remove-agency" tabindex="-1">3.4.6 Remove Agency <a class="header-anchor" href="#_3-4-6-remove-agency" aria-label="Permalink to &quot;3.4.6 Remove Agency&quot;">​</a></h1><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>The Owner of an Agency selects Remove in the Agency settings and confirms the removal dialog; or later selects Restore on an Agency that was removed within the last 30 days.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Agency Owner.</li><li><strong>Purpose:</strong> Let the Owner take an Agency out of use without losing it, so it can be brought back if the Owner changes their mind within 30 days.</li><li><strong>Interface:</strong> Remove action in the Agency settings, behind a two-step confirmation dialog that asks the Owner to type the Agency name and states the consequences, including that the Workspaces of the Agency are affected too. Restore is available on removed Agencies within the 30-day window.</li><li><strong>Data Processing:</strong> The system loads the Agency, confirms the caller is its Owner, then marks the Agency as soft-deleted with the removal timestamp, and marks every Workspace belonging to that Agency the same way, recording the same removal timestamp on each of them. Restoring marks the Agency active again and clears the removal timestamp, and does the same for the Workspaces that were removed in that same removal batch — Workspaces that had already been removed on their own keep their removed state.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Remove Agency dialog:</p><ul><li>A two-step confirmation: the Owner types the Agency name to confirm.</li><li>The dialog lists the consequences, notably that the Workspaces of the Agency are removed along with it.</li><li>A Restore action on removed Agencies, available for 30 days after the removal.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> The Agency identifier (<code>agencyId</code>) and a signed-in session as its Owner.</li><li><strong>Input optional:</strong> None.</li><li><strong>System data:</strong> The status and removal timestamp of the Agency (EntityStatus: ACTIVE / SOFT_DELETED) and the status and removal timestamp of every Workspace belonging to the Agency.</li><li><strong>Output:</strong> The removal leaves no profile to show. The restore returns the Agency profile with the status ACTIVE.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-26 (analogous):</strong> Delete Agency is Owner-only, mirroring the rule that delete Workspace is <code>OWNER</code>-only (BR-26). Anybody else is refused with <code>403 NOT_AGENCY_OWNER</code>.</li><li>Removal is soft: the Agency is marked SOFT_DELETED and stamped with the removal time. Nothing is erased, and the Agency can be restored afterwards.</li><li>Removal cascades to the Workspaces of the Agency: each of them is marked SOFT_DELETED and stamped with the same removal time as the Agency.</li><li>Restore is allowed only on an Agency that is currently SOFT_DELETED; otherwise <code>400 AGENCY_NOT_DELETED</code>.</li><li>Restore is allowed only within 30 days of the removal timestamp; beyond that window, <code>410 RESTORE_WINDOW_EXPIRED</code>.</li><li>Restore marks the Agency ACTIVE with its removal timestamp cleared, and does the same for the Workspaces whose removal timestamp matches the removal batch exactly. A Workspace that had already been removed on its own beforehand keeps its removed state and is not brought back.</li><li>When the 30-day window passes without a restore, the Agency may eventually be erased for good by a periodic clean-up. That clean-up is designed separately and is not part of this feature today.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>Caller is not the Agency Owner → Display: MSG39</li><li>Agency does not exist → Display: MSG38</li><li>Restore called on an Agency that was never removed → <code>400 AGENCY_NOT_DELETED</code>.</li><li>Restore attempted more than 30 days after the removal → <code>410 RESTORE_WINDOW_EXPIRED</code>.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>The Owner selects Remove in the Agency settings.</li><li>The confirmation dialog states the consequences, including that the Workspaces of the Agency are removed along with it, and asks the Owner to type the Agency name.</li><li>The Owner confirms.</li><li>The system loads the Agency and confirms the caller is its Owner.</li><li>The system marks the Agency SOFT_DELETED with the current time.</li><li>The system marks every Workspace belonging to the Agency SOFT_DELETED with the same removal time; toast MSG93.</li><li>The client shows a confirmation and takes the user back to the Agency list.</li><li>Within 30 days, the Owner selects Restore on that Agency.</li><li>The system loads the Agency and confirms the caller is its Owner, that the Agency is SOFT_DELETED, and that the removal happened less than 30 days ago.</li><li>The system marks the Agency ACTIVE with the removal timestamp cleared, and does the same for the Workspaces removed in that same batch.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>4.a1: Agency does not exist → <code>404 AGENCY_NOT_FOUND</code>, toast MSG38. 4.a2: The Owner returns to the Agency list.</li><li>4.b1: Caller is not the Agency Owner → <code>403 NOT_AGENCY_OWNER</code>, toast MSG39; nothing changes. 4.b2: The caller returns to the Agency list.</li><li>9.a1: Restore called on an Agency that was never removed → <code>400 AGENCY_NOT_DELETED</code>, toast MSG38 (closest fit — no dedicated MSG code for this case). 9.a2: The Owner reloads the Agency list, which shows it as already active.</li><li>9.b1: Restore attempted after the 30-day window → <code>410 RESTORE_WINDOW_EXPIRED</code>, toast MSG38 (closest fit — no dedicated MSG code for this case). 9.b2: The Owner accepts the Agency stays removed, or creates a new one.</li><li>10.a1: The Owner removed the Agency by mistake and restores it within 30 days → the Workspaces removed in that same batch become ACTIVE again; no error. 10.a2: The Owner continues working in the restored Agency and its Workspaces.</li><li>10.b1: A Workspace had already been removed on its own beforehand (3.4.15) → it is not brought back when the Agency is restored, because its removal timestamp differs from the removal batch; no error. 10.b2: The Owner restores that Workspace separately if still within its own window.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>After removal: the Agency and its Workspaces carry the SOFT_DELETED status and the same removal timestamp. Nothing is erased.</li><li>After a restore within the window: the Agency is ACTIVE with no removal timestamp, and the Workspaces from the same removal batch are ACTIVE again, while Workspaces removed on their own stay removed.</li></ul>',22)])])}const y=t(s,[["render",i]]);export{g as __pageData,y as default};
